tasks.starter:
// Each Context: { slots: [...], outer: Context|null }
function makeCtx(slots, outer) {
  return { slots, outer };
}
// Resolve a reference compiled to (depth, slot): hop 'outer' depth times.
function resolve(ctx, depth, slot) {
  let c = ctx;
  for (let i = 0; i < depth; i++) c = c.outer;
  return c.slots[slot];
}

const script = makeCtx(['PI'], null);          // script context
const outer  = makeCtx(['total'], script);     // outer() frame
const inner  = makeCtx(['i'], outer);          // inner() frame

// From inner, 'i' is (0,0); 'total' is (1,0); 'PI' is (2,0).
const i     = resolve(inner, 0, 0);
const total = resolve(inner, 1, 0);
const pi    = resolve(inner, 2, 0);
console.log(i + ' ' + total + ' ' + pi);

function computeRate(expr, base) {
  // sloppy eval: could declare vars into THIS scope -> scope stays dynamic
  return eval(expr) * base;
}

model.en:
Make the function strict so <code>eval</code> can no longer leak declarations into the enclosing scope, which lets V8 resolve every local to a fixed slot and optimise the function:<br><code>function computeRate(expr, base) {
  'use strict';
  return eval(expr) * base;
}</code><br>In strict mode an indirect or direct eval runs in its own scope and cannot create variables in <code>computeRate</code>, so the scope stays statically known. Even better, avoid <code>eval</code> entirely — use a safe expression evaluator or a function table — but if eval must stay, strict mode is what keeps the surrounding scope (and its hot identifier reads) optimisable.

model.ru:
Сделай функцию строгой, чтобы <code>eval</code> больше не мог протекать объявлениями в охватывающую область — это позволит V8 разрешить каждую локальную в фиксированный слот и оптимизировать функцию:<br><code>function computeRate(expr, base) {
  'use strict';
  return eval(expr) * base;
}</code><br>В strict mode прямой или косвенный eval работает в собственной области и не может создавать переменные в <code>computeRate</code>, поэтому область остаётся статически известной. Ещё лучше — вовсе отказаться от <code>eval</code> в пользу безопасного вычислителя выражений или таблицы функций — но если eval должен остаться, именно strict mode сохраняет охватывающую область (и её горячие чтения идентификаторов) оптимизируемой.
